// Try primary URL (App Proxy). If it returns 404, attempt fallback with relative proxy path.
function doZipFetch(url) {
  return fetch(url).then(function(r) {
    if (r.status === 404 && url.indexOf("http") === 0 && url !== (_proxyPath + "/api/zip-check?shop=" + encodeURIComponent(SHOP) + "&zip=" + encodeURIComponent(zip))) {
      // App Proxy URL returned 404 — try relative proxy path as fallback
      var fallbackUrl = _proxyPath + "/api/zip-check?shop=" + encodeURIComponent(SHOP) + "&zip=" + encodeURIComponent(zip);
      console.warn("[Pinzo] Primary URL returned 404, retrying with proxy fallback: " + fallbackUrl);
      return fetch(fallbackUrl);
    }
    return r;
  });
}

